export const salesDiscoveryLines: Line[] = [
  {"id":"L001","speaker":"marcus","text":"Rachel, Omar, thanks for making the time. I know Thursdays are busy for you.","start":2,"end":7.7},
  {"id":"L002","speaker":"rachel","text":"Of course. We've been looking forward to it, honestly.","start":8.2,"end":11.4},
  {"id":"L003","speaker":"marcus","text":"I brought Jordan, who runs product, because I think a lot of your questions will be about where the product is going.","start":12,"end":20.5},
  {"id":"L004","speaker":"jordan","text":"Hi both. Happy to be here, and happy to be grilled.","start":21.3,"end":25.8},
  {"id":"L005","speaker":"omar","text":"We'll be gentle. Mostly.","start":26.3,"end":27.8},
  {"id":"L006","speaker":"marcus","text":"So my plan was to spend most of this on your world, not on us. Is that okay?","start":28.5,"end":35.8},
  {"id":"L007","speaker":"rachel","text":"That's perfect.","start":36.6,"end":37.4},
  {"id":"L008","speaker":"marcus","text":"Great. Rachel, can you walk us through how field work runs today, end to end?","start":38.2,"end":44.2},
  {"id":"L009","speaker":"rachel","text":"Sure. So we have about four hundred technicians across eleven regions. Mostly refrigeration and cold-chain equipment at distribution centers.","start":45.9,"end":53.1},
  {"id":"L010","speaker":"rachel","text":"Dispatch is centralized in Columbus, and today they schedule everything in a mix of our old ERP and spreadsheets. A lot of spreadsheets.","start":53.3,"end":62.6},
  {"id":"L011","speaker":"rachel","text":"Technicians get their jobs on a mobile app that came with the ERP, which, I'll be honest, they hate.","start":62.8,"end":70.2},
  {"id":"L012","speaker":"marcus","text":"What do they hate about it most?","start":70.7,"end":73.5},
  {"id":"L013","speaker":"rachel","text":"It's slow, it logs them out constantly, and if they lose signal in a freezer, which happens all the time, they lose whatever they typed.","start":74.2,"end":83.7},
  {"id":"L014","speaker":"rachel","text":"Our freezers are basically Faraday cages. There is no signal in there. None.","start":84,"end":89.3},
  {"id":"L015","speaker":"jordan","text":"That's a story we hear a lot. How do they work around it today?","start":90.1,"end":95.1},
  {"id":"L016","speaker":"rachel","text":"Paper. They write it down in the freezer, then type it into the app in the truck. So every job is entered twice.","start":95.9,"end":105.4},
  {"id":"L017","speaker":"marcus","text":"Do you have a sense of what that costs you?","start":105.8,"end":109.5},
  {"id":"L018","speaker":"rachel","text":"We did a time study last year. It's about twenty-two minutes per job of re-entry and fixing errors.","start":109.8,"end":116.3},
  {"id":"L019","speaker":"rachel","text":"Across roughly nine thousand jobs a month, that's a lot of hours.","start":116.6,"end":121},
  {"id":"L020","speaker":"omar","text":"It's about thirty-three hundred hours a month. I ran the numbers for the business case.","start":121.4,"end":127},
  {"id":"L021","speaker":"marcus","text":"Thirty-three hundred hours a month. That's real.","start":127.6,"end":130.4},
  {"id":"L022","speaker":"rachel","text":"And that's before you count the errors. We had a compliance audit flag last quarter because temperature readings were transcribed wrong.","start":130.9,"end":139.1},
  {"id":"L023","speaker":"marcus","text":"What happened with that?","start":139.6,"end":141.1},
  {"id":"L024","speaker":"rachel","text":"A fine, and a very unpleasant meeting with our VP. I'd rather not repeat it.","start":141.7,"end":147.8},
  {"id":"L025","speaker":"marcus","text":"So if this goes well, what does success look like for you a year from now?","start":149.5,"end":155.6},
  {"id":"L026","speaker":"rachel","text":"Re-entry time goes to basically zero. Temperature data captured once, at the equipment, with a timestamp.","start":156.2,"end":162.4},
  {"id":"L027","speaker":"rachel","text":"And I want first-time fix rate up. Right now it's about seventy-one percent. I'd love to see eighty.","start":162.6,"end":169.6},
  {"id":"L028","speaker":"marcus","text":"Why does first-time fix matter so much to you specifically?","start":170.3,"end":174.4},
  {"id":"L029","speaker":"rachel","text":"Because every repeat visit is a truck roll, and a truck roll costs us about three hundred and eighty dollars all-in.","start":175.1,"end":183.8},
  {"id":"L030","speaker":"jordan","text":"Is the first-time fix problem mostly parts, or mostly information?","start":184.4,"end":188.5},
  {"id":"L031","speaker":"rachel","text":"Information, mostly. The tech shows up without the asset history, doesn't know what the last person did, and guesses.","start":189.1,"end":196.6},
  {"id":"L032","speaker":"jordan","text":"That's one of the strongest parts of our product, the asset history on the work order. I'll make sure we show you that properly.","start":197.3,"end":206.8},
  {"id":"L033","speaker":"marcus","text":"Okay. Can I ask about the decision itself? Who's involved in choosing a platform like this?","start":208.3,"end":214.1},
  {"id":"L034","speaker":"rachel","text":"I'm the one driving it. I own field operations, and the budget is mine.","start":214.8,"end":220.6},
  {"id":"L035","speaker":"rachel","text":"But anything over two hundred and fifty thousand needs sign-off from our CFO, Daniel.","start":220.8,"end":226.1},
  {"id":"L036","speaker":"marcus","text":"Have you talked to Daniel about this project yet?","start":226.5,"end":229.8},
  {"id":"L037","speaker":"rachel","text":"Informally. He's supportive, but he'll want to see the business case. Omar's numbers will help.","start":230.3,"end":236.3},
  {"id":"L038","speaker":"marcus","text":"And Omar, where does IT come in?","start":237,"end":239.7},
  {"id":"L039","speaker":"omar","text":"Security review, and integration with the ERP. Those are my two gates.","start":240.5,"end":244.8},
  {"id":"L040","speaker":"omar","text":"Security is the bigger one. We have a vendor risk process, and it's strict. We had a breach at a vendor two years ago, so everyone's careful now.","start":245.1,"end":255.2},
  {"id":"L041","speaker":"marcus","text":"What does the vendor risk process require?","start":255.9,"end":258.5},
  {"id":"L042","speaker":"omar","text":"SOC 2 Type Two report, SAML single sign-on, and a pen test summary within the last twelve months.","start":259.2,"end":265.9},
  {"id":"L043","speaker":"omar","text":"Those are hard requirements. Not nice-to-haves. I can't get an exception on any of them.","start":266.1,"end":271.8},
  {"id":"L044","speaker":"jordan","text":"I want to be upfront about where we are on those, because I'd rather you hear it from us.","start":272.5,"end":279.4},
  {"id":"L045","speaker":"jordan","text":"We don't have a SOC 2 Type Two report today. We're targeting the start of the observation window in early January.","start":279.6,"end":288.2},
  {"id":"L046","speaker":"jordan","text":"SSO is on the roadmap for Q1, and we're sequencing it early.","start":288.4,"end":292.9},
  {"id":"L047","speaker":"omar","text":"Okay. Appreciate the honesty. Most vendors hand-wave on that question.","start":293.7,"end":297.7},
  {"id":"L048","speaker":"omar","text":"A target date with a bridge letter might be enough to let us start procurement, but I can't sign the final contract without the report.","start":298,"end":307.5},
  {"id":"L049","speaker":"marcus","text":"Understood. That's helpful.","start":308.4,"end":309.5},
  {"id":"L050","speaker":"marcus","text":"And what about the paper side? Legal, procurement, how long does that usually take for you?","start":309.8,"end":316.2},
  {"id":"L051","speaker":"omar","text":"Procurement is about six weeks once security clears. Legal is usually two to three weeks in parallel.","start":317,"end":323.1},
  {"id":"L052","speaker":"rachel","text":"And we'd want to start with a pilot in two regions before rolling out everywhere.","start":323.7,"end":329.4},
  {"id":"L053","speaker":"marcus","text":"That's what we'd recommend too. Which regions?","start":329.8,"end":332.3},
  {"id":"L054","speaker":"rachel","text":"Columbus and Atlanta. Columbus because dispatch is there, Atlanta because it has the worst freezer problem.","start":332.9,"end":338.9},
  {"id":"L055","speaker":"marcus","text":"Can I ask who else you're looking at?","start":340.7,"end":344},
  {"id":"L056","speaker":"rachel","text":"We're talking to one other vendor seriously. I'd rather not say who, but they're bigger than you.","start":344.7,"end":350.8},
  {"id":"L057","speaker":"marcus","text":"That's fair. What do you like about them?","start":351.6,"end":354.5},
  {"id":"L058","speaker":"rachel","text":"They already have SSO and the SOC 2 report. Omar loves that.","start":354.9,"end":359.7},
  {"id":"L059","speaker":"omar","text":"I do love that.","start":360.3,"end":361.9},
  {"id":"L060","speaker":"rachel","text":"But their offline story is weak. Their demo crashed when we turned off the Wi-Fi. Which was kind of funny, honestly.","start":362.7,"end":371},
  {"id":"L061","speaker":"jordan","text":"Did they have an answer for it?","start":371.7,"end":374.3},
  {"id":"L062","speaker":"rachel","text":"They said offline is on their roadmap for next year.","start":374.9,"end":378.8},
  {"id":"L063","speaker":"marcus","text":"So if we had both, offline and the enterprise security pieces, where would that leave us?","start":379.4,"end":385.7},
  {"id":"L064","speaker":"rachel","text":"Honestly, in a strong position. Offline is the thing my technicians will actually notice. Omar's requirements are the thing that gets it through the door.","start":386.5,"end":396.4},
  {"id":"L065","speaker":"marcus","text":"That's a really clear way to put it.","start":397.3,"end":400.3},
  {"id":"L066","speaker":"marcus","text":"Okay, I want to be respectful of time. Let me suggest next steps.","start":401.5,"end":406.3},
  {"id":"L067","speaker":"marcus","text":"One, I'll send Omar our security overview and the timeline for SOC 2 and SSO, including a draft bridge letter.","start":406.6,"end":414.2},
  {"id":"L068","speaker":"omar","text":"That would help. Send it to me directly.","start":414.7,"end":417.6},
  {"id":"L069","speaker":"marcus","text":"Two, Jordan, can we set up a technical demo focused on offline and asset history? Ideally with a tablet in a freezer, if Rachel's game.","start":418.2,"end":427.6},
  {"id":"L070","speaker":"rachel","text":"Oh, I am absolutely game. We have a test freezer in Columbus.","start":428.3,"end":433},
  {"id":"L071","speaker":"jordan","text":"I love that. Let's do it in person. I'll get the offline beta build on a tablet for the demo.","start":433.5,"end":441},
  {"id":"L072","speaker":"marcus","text":"Three, Rachel, would you be open to a short call with Daniel, so we can understand what he needs in the business case?","start":441.8,"end":451.2},
  {"id":"L073","speaker":"rachel","text":"Yes. I'll ask him. He's traveling next week, so it might be the week after.","start":451.5,"end":457.5},
  {"id":"L074","speaker":"marcus","text":"Perfect. And I'll draft a business case outline using Omar's numbers, so you have something to bring him.","start":458.1,"end":464.8},
  {"id":"L075","speaker":"omar","text":"That works.","start":465.2,"end":465.9},
  {"id":"L076","speaker":"rachel","text":"One question before we go. What's your pricing look like for four hundred technicians? Ballpark.","start":466.4,"end":472.3},
  {"id":"L077","speaker":"marcus","text":"Ballpark, for that size, with the enterprise tier, somewhere in the range of four-fifty to five-fifty a year, depending on modules.","start":473,"end":480.6},
  {"id":"L078","speaker":"rachel","text":"Okay. That's in range. Not cheap, but in range.","start":481.1,"end":484.6},
  {"id":"L079","speaker":"marcus","text":"I'll put a proper proposal together after the demo.","start":485.2,"end":488.7},
  {"id":"L080","speaker":"rachel","text":"Great. Thanks, both of you. This was genuinely useful.","start":489.5,"end":492.8},
  {"id":"L081","speaker":"jordan","text":"Thank you. Talk soon.","start":493.4,"end":494.9},
];
